 main.className='templates-page';main.innerHTML=`<div class="page-heading"><div><h1>试卷与版式</h1></div><button id="template-agent" class="button secondary">复制出卷指令 ${icon('copy')}</button></div><div class="catalog-controls"><div class="segmented"><button data-catalog="cases" aria-pressed="${catalogMode==='cases'}">试卷案例</button><button data-catalog="topics" aria-pressed="${catalogMode==='topics'}">考公考研与工程</button><button data-catalog="templates" aria-pressed="${catalogMode==='templates'}">通用练习版式</button></div>${catalogMode!=='templates'?`<input id="case-search" type="search" placeholder="搜索学科、考试或试卷" aria-label="搜索试卷" value="${escape(caseSearch)}">`:''}</div><div class="filter-tabs" role="group" aria-label="考试类型">${families.map(f=>`<button data-family="${escape(f)}" aria-pressed="${templateFilter===f}">${escape(f)}</button>`).join('')}</div><div class="template-grid${catalogMode==='cases'?' real-case-grid':catalogMode==='topics'?' topic-case-grid':''}">${catalogMode==='templates'?list.map(templateCard).join(''):catalogMode==='topics'?topics.map(t=>`<button class="template-card topic-case-card" data-topic="${escape(t.id)}"><div class="topic-paper-type">${icon('file')}<span>${escape(topicFamilyNames[t.family])} · ${escape(t.subject)}</span></div><h2>${escape(t.title)}</h2>${t.description?`<p>${escape(t.description)}</p>`:''}<div class="template-card-meta"><span>${t.questionCount} 项 · ${t.totalScore} 分${t.mode==='bank'?'':' · '+t.durationMinutes+' 分钟'}</span><span>${t.mode==='bank'?'打开题库':'打开试卷'} ${icon('arrow')}</span></div></button>`).join('')||'<p class="catalog-empty">没有匹配的试卷。</p>':[...cases.map(p=>`<button class="template-card real-case-card" data-case="${escape(p.practiceId)}"><div class="template-thumbnail"><img src="${caseThumbnail(p)}" alt="${escape(p.title)}首页" loading="lazy"></div><div class="template-card-text"><div class="case-card-heading"><span>${escape(p.level)} / ${escape(p.subject)}</span></div><h2>${escape(p.title)}</h2><div class="template-card-meta"><span>${questionsOf(p).length} 项 · ${scoreText(specFor(p),p.totalScore)}</span><span>打开试卷 ${icon('arrow')}</span></div></div></button>`),...featuredTopics.map(t=>`<button class="template-card real-case-card" data-topic="${escape(t.id)}"><div class="template-thumbnail"><img src="${t.pages[0]??''}" alt="${escape(t.title)}首页" loading="lazy"></div><div class="template-card-text"><div class="case-card-heading"><span>${escape(t.level)} / ${escape(t.subject)}</span></div><h2>${escape(t.title)}</h2><div class="template-card-meta"><span>${t.questionCount} 项 · ${t.totalScore} 分</span><span>打开试卷 ${icon('arrow')}</span></div></div></button>`)].join('')||'<p class="catalog-empty">没有匹配的试卷。</p>'}</div>`;
 main.querySelectorAll<HTMLButtonElement>('[data-family]').forEach(b=>b.onclick=()=>{templateFilter=b.dataset.family!;renderTemplates();});
